#!/usr/bin/env python3
"""
Zero-token local evidence indexer for Northstar Shop Deletion Audit dataset.
Correlates trace events across logs and records into SQLite cache/northstar.db.
"""

from __future__ import annotations

import csv
import json
import re
import sqlite3
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

KV_REGEX = re.compile(r'(\w+)=(?:"([^"]*)"|(\S+))')


def _clean_str(val: Any) -> Optional[str]:
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.lower() in ("null", "none"):
        return None
    return s


def _parse_iso_ts(ts_str: Any) -> Optional[datetime]:
    if not ts_str:
        return None
    s = str(ts_str).strip()
    if not s or s.lower() in ("null", "none"):
        return None
    try:
        return datetime.fromisoformat(s.replace("Z", "+00:00"))
    except Exception:
        return None


def index_unstructured_evidence(
    evidence_dir: Path = Path("dataset/evidence"),
    conn: Optional[sqlite3.Connection] = None,
) -> None:
