"import csv
import json
import re
from pathlib import Path

cases_22 = [
    'case_56', 'case_58', 'case_59', 'case_60', 'case_206', 'case_253', 'case_257',
    'case_260', 'case_304', 'case_309', 'case_403', 'case_408', 'case_409', 'case_411',
    'case_412', 'case_503', 'case_506', 'case_512', 'case_517', 'case_519', 'case_521', 'case_525'
]

with open('dataset/deletion_requests.csv', encoding='utf-8-sig') as f:
    requests = {r['case_id']: r for r in csv.DictReader(f)}

with open('dataset/user_identities.csv', encoding='utf-8-sig') as f:
    uids = {r['email'].lower(): r['user_id'] for r in csv.DictReader(f) if r.get('email')}

emails_to_case = {}
uids_to_case = {}
for cid in cases_22:
    req = requests[cid]
    em = req['email'].lower()
    emails_to_case[em] = cid
    uid = uids.get(em)
    if uid:
        uids_to_case[uid] = cid

print(f"Loaded {len(cases_22)} cases.")

# Scan all SQL and JSON evidence files for these emails and uids
found_items = []
ev_dir = Path("dataset/evidence")
for p in ev_dir.rglob("*"):
    if not p.is_file():
        continue
    txt = p.read_text("utf-8", "ignore")
    for em, cid in emails_to_case.items():
        if em in txt.lower():
            # Find matching lines
            for line in txt.splitlines():
                if em in line.lower():
                    found_items.append((cid, em, p.name, line.strip()[:160]))
    for uid, cid in uids_to_case.items():
        if re.search(rf"\b{uid}\b", txt):
            for line in txt.splitlines():
                if re.search(rf"\b{uid}\b", line):
                    found_items.append((cid, uid, p.name, line.strip()[:160]))

# Deduplicate
seen = set()
for cid, ident, fname, sample in sorted(found_items, key=lambda x: (x[0], x[2])):
    k = (cid, fname, sample[:60])
    if k not in seen:
        seen.add(k)
        print(f"[{cid}] ({ident}) in {fname}: {sample}")
